export interface VendoredPart {
  /** base64 little-endian Float32 xyz triples, part-local metres */
  pos: string;
  /** base64 little-endian Float32 uv pairs (hm08 layout, v=0 bottom) */
  uv: string;
  /** base64 little-endian Uint16 triangle indices */
  idx: string;
  vertCount: number;
  triCount: number;
  /** minX,minY,minZ,maxX,maxY,maxZ in part-local metres */
  bbox: [number, number, number, number, number, number];
}

export interface VendoredSkinAtlas {
  /** base64 JPEG, res x res, 2x2 tiles, sRGB */
  jpegB64: string;
  res: number;
  tiles: number;
  /** tile names dark -> pale; tile t occupies UV rect
   *  [ (t%2)/2 .. (t%2+1)/2 ] x [ (t/2|0)/2 .. (t/2|0+1)/2 ] */
  tileOrder: string[];
  /** per-tile LINEAR-space mean rgb over head-sampled texels — the
   *  material divides by this so SKIN_RAMP keeps owning average tone */
  tileMeansLinear: [number, number, number][];
  sourceRepo: string;
  sourceCommit: string;
  sources: { path: string; sha256: string; bytes: number }[];
}

export interface VendoredFigure {
  name: string;
  phenotypes: Record<string, number>;
  bodyHeightAnny: number;
  scale: number;
  head: VendoredPart;
  eyes: VendoredPart;
  handL: VendoredPart;
  handR: VendoredPart;
  /** fitted CC0 system hair (part-local like head; ramp-colored,
   *  uv is a 0.5 filler) */
  hair: VendoredPart;
  hairStyle: string;
  forearmAxisL: [number, number, number];
  forearmAxisR: [number, number, number];
}

